110	    /**
111	     * Immutable structured audit event emitted through {@link #AUDIT} on a successful owner create.
112	     * <p>The identifier it carries is the owner's <em>current</em> primary identifier — its unified
113	     * {@code memberId} — so a downstream consumer always reads the live primary key from the one
114	     * {@code memberId} field. See {@link #primaryIdentifier(Owner)}.
115	     */
116	    private record OwnerCreatedEvent(long seq, Integer ownerId, String identifier, Integer membershipLevel) {
117	
118	        String toJson() {
119	            return "{\"seq\":" + seq
120	                + ",\"ownerId\":" + ownerId
121	                + ",\"memberId\":" + jsonString(identifier)
122	                + ",\"membershipLevel\":" + membershipLevel
123	                + ",\"event\":\"OWNER_CREATED\"}";
124	        }
125	
126	        private static String jsonString(String s) {
127	            if (s == null) {
128	                return "null";
129	            }
130	            StringBuilder sb = new StringBuilder(s.length() + 2).append('"');
131	            for (int i = 0; i < s.length(); i++) {
132	                char c = s.charAt(i);
133	                switch (c) {
134	                    case '"' -> sb.append("\\\"");
135	                    case '\\' -> sb.append("\\\\");
136	                    case '\n' -> sb.append("\\n");
137	                    case '\r' -> sb.append("\\r");
138	                    case '\t' -> sb.append("\\t");
139	                    default -> sb.append(c);
140	                }
141	            }
142	            return sb.append('"').toString();
143	        }
144	    }
