216	    /**
217	     * Normalizes an address on create: leading/trailing whitespace is trimmed, every run of internal
218	     * whitespace is collapsed to a single space, the value is upper-cased and common abbreviations are
219	     * expanded token-by-token ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The
220	     * normalized value is what gets stored, returned and used for every address comparison; a value
221	     * that is blank (or {@code null}) normalizes to the empty string so the required-field check
222	     * rejects it.
223	     *
224	     * @param address the raw address as supplied by the caller, may be {@code null}
225	     * @return the normalized address ({@code ""} when blank or {@code null})
226	     */
227	    private static String normalizeAddress(String address) {
228	        if (address == null) {
229	            return "";
230	        }
231	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
232	        if (collapsed.isEmpty()) {
233	            return "";
234	        }
235	        String[] tokens = collapsed.split(" ");
236	        StringBuilder sb = new StringBuilder(collapsed.length());
237	        for (int i = 0; i < tokens.length; i++) {
238	            String token = tokens[i];
239	            switch (token) {
240	                case "ST" -> token = "STREET";
241	                case "RD" -> token = "ROAD";
242	                case "AVE" -> token = "AVENUE";
243	                default -> { }
244	            }
245	            if (i > 0) {
246	                sb.append(' ');
247	            }
248	            sb.append(token);
249	        }
250	        return sb.toString();
251	    }
