253	    /**
254	     * Resolves and normalizes the owner's address on create, supporting both the structured form
255	     * ({@code addressLine1} / {@code addressLine2}) and the flat {@code address} form kept for
256	     * backward compatibility. Whichever address fields are supplied are normalized (see
257	     * {@link #normalizeAddress(String)}). The structured form is preferred when present: when
258	     * {@code addressLine1} is non-blank the composed {@code address} is the normalized
259	     * {@code addressLine1}, with a single space and the normalized {@code addressLine2} appended when
260	     * {@code addressLine2} is present; otherwise the composed {@code address} is the normalized flat
261	     * {@code address}. The normalized structured fields are written back so they are stored and
262	     * returned, and the composed value is written to {@code address} so everything that reads the
263	     * address (the household hash, postcode validation and locality) uses the structured fields when
264	     * present, falling back to the flat address. When neither form supplies an address the composed
265	     * {@code address} is blank, so the required-field check rejects it.
266	     *
267	     * @param ownerFieldsDto the owner payload whose address fields are normalized in place
268	     */
269	    private static void applyAddress(OwnerFieldsDto ownerFieldsDto) {
270	        String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
271	        String line2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
272	        String flat = normalizeAddress(ownerFieldsDto.getAddress());
273	        String composed;
274	        if (!line1.isEmpty()) {
275	            composed = line2.isEmpty() ? line1 : line1 + " " + line2;
276	        } else {
277	            composed = flat;
278	        }
279	        ownerFieldsDto.setAddressLine1(line1.isEmpty() ? null : line1);
280	        ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
281	        ownerFieldsDto.setAddress(composed);
282	    }
