284	    /**
285	     * Normalizes a telephone on create into E.164 form. Spaces, dashes and brackets are stripped.
286	     * A leading {@code +} and its country code are kept as given; otherwise the country code
287	     * {@code +61} is assumed and a single leading {@code 0} is dropped from the national digits.
288	     * The result must carry 8 to 15 digits after the {@code +}. In addition, when the country code
289	     * is recognized the national number must have the exact length that code requires ({@code +61}
290	     * expects 9 national digits, {@code +1} expects 10). Returns the E.164 string to be stored and
291	     * returned.
292	     *
293	     * @param telephone the raw telephone as supplied by the caller
294	     * @return the normalized E.164 telephone (a {@code +} followed by 8 to 15 digits)
295	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number, or its
296	     *     national-number length is wrong for its country code
297	     */
298	    private static String normalizeTelephone(String telephone) {
299	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
300	        String e164;
301	        if (cleaned.startsWith("+")) {
302	            e164 = "+" + cleaned.substring(1);
303	        } else {
304	            String national = cleaned;
305	            if (national.startsWith("0")) {
306	                national = national.substring(1);
307	            }
308	            e164 = "+61" + national;
309	        }
310	        String digits = e164.substring(1);
311	        if (!digits.matches("\\d{8,15}")) {
312	            throw new InvalidTelephoneException(
313	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
314	        }
315	        if (digits.startsWith("61")) {
316	            requireNationalLength(digits.substring(2), 9, "+61");
317	        } else if (digits.startsWith("1")) {
318	            requireNationalLength(digits.substring(1), 10, "+1");
319	        }
320	        return e164;
321	    }
322	
323	    /**
324	     * Enforces that the national portion of an E.164 number has the exact number of digits its
325	     * country code requires.
326	     *
327	     * @param national the national-number digits (the part after the country code)
328	     * @param expected the exact national-number length the country code requires
329	     * @param countryCode the country code, for the error message
330	     * @throws InvalidTelephoneException if {@code national} does not have exactly {@code expected} digits
331	     */
332	    private static void requireNationalLength(String national, int expected, String countryCode) {
333	        if (national.length() != expected) {
334	            throw new InvalidTelephoneException(
335	                "Telephone with country code '" + countryCode + "' must have " + expected
336	                    + " national digits");
337	        }
338	    }
