340	    /**
341	     * Normalizes an optional email. An absent or blank email is left unset (returns {@code null});
342	     * a present value must be a syntactically valid address and is stored and returned lower-cased.
343	     *
344	     * @param email the raw email as supplied by the caller, may be {@code null}
345	     * @return the lower-cased email, or {@code null} when none was supplied
346	     * @throws InvalidEmailException if a value is present but is not a syntactically valid address
347	     */
348	    private static String normalizeEmail(String email) {
349	        if (email == null || email.isBlank()) {
350	            return null;
351	        }
352	        String trimmed = email.trim();
353	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
354	            throw new InvalidEmailException("Email must be a syntactically valid address");
355	        }
356	        String lowerCased = trimmed.toLowerCase(Locale.ROOT);
357	        String domain = lowerCased.substring(lowerCased.indexOf('@') + 1);
358	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
359	            throw new InvalidEmailException("Email domain is not allowed");
360	        }
361	        return lowerCased;
362	    }
