364	    /**
365	     * Derives the single duplicate-detection key that consolidates the former separate telephone,
366	     * email and household checks. The key is the lower-case hex SHA-256 of
367	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, with an empty segment
368	     * for an absent telephone or email. Because the telephone is part of the key, two owners that
369	     * differ in any one segment (for example two members of the same household with different
370	     * telephones) produce different keys and are therefore not hard duplicates.
371	     *
372	     * @param normalizedTelephone the E.164 telephone of the owner
373	     * @param email the lower-cased email of the owner, may be {@code null}
374	     * @param lastName the last name of the owner, reduced to its Soundex code, may be {@code null}
375	     * @return the derived identity key
376	     */
377	    private static String deriveIdentityKey(String normalizedTelephone, String email, String lastName) {
378	        return org.springframework.samples.petclinic.util.IdentityKeys.identityKey(
379	            normalizedTelephone, email, lastName);
380	    }
381	
382	    /**
383	     * Rejects a create only when the new owner's whole {@code identityKey} equals that of an existing
384	     * owner. This one check replaces the former separate telephone, email and household duplicate
385	     * checks: only an exact full-key match is a duplicate, so two owners that differ in any single
386	     * segment are both allowed. Each existing owner's key is derived from its stored, already
387	     * normalized telephone, email and household identifier.
388	     *
389	     * @param identityKey the derived identity key of the owner being created
390	     * @throws DuplicateIdentityException if another owner already has this identity key
391	     */
392	    /**
393	     * The existing owners considered by the create endpoint's duplicate and identity checks:
394	     * every owner that is not soft-deleted. A soft-deleted owner retains its row but is ignored
395	     * here, so a create that would otherwise be blocked by it is allowed.
396	     *
397	     * @return a stream of the owners not flagged deleted
398	     */
399	    private java.util.stream.Stream<Owner> activeOwners() {
400	        return this.clinicService.findAllOwners().stream()
401	            .filter(existing -> !existing.isDeleted());
402	    }
403	
404	    private void rejectDuplicateIdentity(String identityKey) {
405	        boolean inUse = activeOwners()
406	            .anyMatch(existing -> identityKey.equals(
407	                deriveIdentityKey(existing.getTelephone(), existing.getEmail(), existing.getLastName())));
408	        if (inUse) {
409	            throw new DuplicateIdentityException(
410	                "An owner with the same identity key already exists");
411	        }
412	    }
413	
414	    /**
415	     * Finds a soft-match "possible duplicate" for the owner being created: an existing owner that is
416	     * not a hard identity duplicate (its {@code identityKey} differs) but shares the phonetic code of
417	     * this owner's last name (its Soundex) and its postcode. Because the telephone is part of the
418	     * identity key, two owners with the same surname and postcode but different telephones are no
419	     * longer hard duplicates — they surface here as a soft match instead. When the postcode is absent
420	     * no owner can share it, so there is never a match. When several existing owners qualify the one
421	     * with the lowest id is returned, so the result is deterministic.
422	     *
423	     * @param lastName the last name of the owner being created
424	     * @param postcode the postcode of the owner being created, may be {@code null}
425	     * @param identityKey the derived identity key of the owner being created
426	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
427	     */
428	    private Integer findPossibleDuplicateOf(String lastName, String postcode, String identityKey) {
429	        if (postcode == null || postcode.isBlank()) {
430	            return null;
431	        }
432	        String soundex = org.springframework.samples.petclinic.util.IdentityKeys.soundex(lastName);
433	        return activeOwners()
434	            .filter(existing -> soundex.equals(
435	                org.springframework.samples.petclinic.util.IdentityKeys.soundex(existing.getLastName())))
436	            .filter(existing -> postcode.equals(existing.getPostcode()))
437	            .filter(existing -> !identityKey.equals(
438	                deriveIdentityKey(existing.getTelephone(), existing.getEmail(), existing.getLastName())))
439	            .map(Owner::getId)
440	            .filter(java.util.Objects::nonNull)
441	            .min(Integer::compareTo)
442	            .orElse(null);
443	    }
