445	    /**
446	     * Derives the stable household identifier for an owner from its last name and postcode. The value
447	     * is the first twelve hex characters of the SHA-256 of {@code normalizedLastName + '|' + postcode}
448	     * (the last name normalized case-insensitively with surrounding whitespace trimmed; an absent
449	     * postcode contributes the empty string). Because it is a pure function of those two fields, every
450	     * owner with the same last name and postcode is assigned the same identifier automatically, without
451	     * any existing record having to be updated.
452	     *
453	     * @param lastName the last name of the owner being created
454	     * @param postcode the postcode of the owner being created, may be {@code null}
455	     * @return the stable household identifier
456	     */
457	    private static String householdId(String lastName, String postcode) {
458	        String key = normalizeName(lastName) + "|" + (postcode == null ? "" : postcode);
459	        return sha256HexPrefix(key, 12);
460	    }
