462	    /**
463	     * The maximum number of owners a single city may contain. A create whose city already holds this
464	     * many owners is rejected, so a city never grows beyond this capacity.
465	     */
466	    private static final int CITY_CAPACITY = 50;
467	
468	    /**
469	     * Rejects a create whose city already contains {@link #CITY_CAPACITY} or more owners, so no city
470	     * ever exceeds its capacity. Cities are compared case-insensitively with surrounding whitespace
471	     * trimmed. The count reflects the
472	     * state before the new owner is persisted, so it excludes the owner being created.
473	     *
474	     * @param city the city of the owner being created
475	     * @throws CityAtCapacityException if the city already contains {@link #CITY_CAPACITY} owners
476	     */
477	    private void rejectCityAtCapacity(String city) {
478	        String normalizedCity = normalizeName(city);
479	        long ownersInCity = this.clinicService.findAllOwners().stream()
480	            .filter(existing -> normalizedCity.equals(normalizeName(existing.getCity())))
481	            .count();
482	        if (ownersInCity >= CITY_CAPACITY) {
483	            throw new CityAtCapacityException(
484	                "The city already contains the maximum number of owners");
485	        }
486	    }
