488	    /**
489	     * The number of owners a city must already contain before a create in that city is flagged with a
490	     * capacity warning. Once a city holds at least this many owners (but still fewer than
491	     * {@link #CITY_CAPACITY}), the created owner's {@code capacityWarning} is set to {@code true} to
492	     * signal the city is approaching its capacity limit.
493	     */
494	    private static final int CAPACITY_WARNING_THRESHOLD = 40;
495	
496	    /**
497	     * Determines whether a create should be flagged with a capacity warning, i.e. whether the owner's
498	     * city already contains between {@link #CAPACITY_WARNING_THRESHOLD} and {@code CITY_CAPACITY - 1}
499	     * owners (inclusive), indicating the city is approaching its capacity limit. Cities are compared
500	     * case-insensitively with surrounding whitespace trimmed. The count reflects the state before the
501	     * new owner is persisted, so it excludes the owner being created.
502	     *
503	     * @param city the city of the owner being created
504	     * @return {@code true} when the city already holds {@value #CAPACITY_WARNING_THRESHOLD}-49 owners
505	     */
506	    private boolean capacityWarning(String city) {
507	        String normalizedCity = normalizeName(city);
508	        long ownersInCity = this.clinicService.findAllOwners().stream()
509	            .filter(existing -> normalizedCity.equals(normalizeName(existing.getCity())))
510	            .count();
511	        return ownersInCity >= CAPACITY_WARNING_THRESHOLD && ownersInCity < CITY_CAPACITY;
512	    }
