522	     * Rejects a create once {@link #DAILY_OWNER_LIMIT} or more owners have already been created for
523	     * the given business day, counted by {@code registrationDate} equal to the effective (weekend
524	     * rolled forward) registration date of the owner being created. The count reflects the state
525	     * before the new owner is persisted, so it excludes the owner being created.
526	     *
527	     * @param registrationDate the effective business-day registration date of the owner being created
528	     * @throws DailyOwnerLimitExceededException if the day already holds {@link #DAILY_OWNER_LIMIT} owners
529	     */
530	    private void rejectDailyOwnerLimit(LocalDate registrationDate) {
531	        long ownersToday = this.clinicService.findAllOwners().stream()
532	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
533	            .count();
534	        if (ownersToday >= DAILY_OWNER_LIMIT) {
535	            throw new DailyOwnerLimitExceededException(
536	                "The maximum number of owners for today has already been reached");
537	        }
