547	    /**
548	     * Determines whether a create should be flagged with a bulk-signup warning, i.e. whether more than
549	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for the given business day,
550	     * counted by {@code registrationDate} equal to the effective (weekend rolled forward) registration
551	     * date of the owner being created. The count reflects the state before the new owner is persisted,
552	     * so it excludes the owner being created.
553	     *
554	     * @param registrationDate the effective business-day registration date of the owner being created
555	     * @return {@code true} when more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the date
556	     */
557	    private boolean bulkSignupWarning(LocalDate registrationDate) {
558	        long ownersToday = this.clinicService.findAllOwners().stream()
559	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
560	            .count();
561	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
562	    }
