564	    /** Fixed public holidays the business-day roll skips. */
565	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
566	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
567	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
568	        LocalDate.parse("2026-12-28"));
569	
570	    /**
571	     * Rolls a registration date forward to a business day: any date landing on a Saturday, Sunday or
572	     * listed public holiday is advanced one day at a time until it reaches the next non-holiday
573	     * weekday, and any other weekday is returned unchanged.
574	     *
575	     * @param date the effective registration date, supplied or defaulted to the server date
576	     * @return the same date when it is a non-holiday weekday, otherwise the next non-holiday business day
577	     */
578	    private static LocalDate toBusinessDay(LocalDate date) {
579	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
580	                || date.getDayOfWeek() == DayOfWeek.SUNDAY
581	                || PUBLIC_HOLIDAYS.contains(date)) {
582	            date = date.plusDays(1);
583	        }
584	        return date;
585	    }
586	
587	    /**
588	     * Builds the unified member id assigned to an owner on create, formatted
589	     * {@code '<REGION><FY><HASH8><CHK>'}. {@code REGION} is the region code derived from the owner's
590	     * postcode (the region whose inclusive range contains the postcode, or {@code 'UNKNOWN'} when the
591	     * postcode is absent or in no known range). {@code FY} is the 2-digit fiscal year (the last two
592	     * digits of the calendar year in which the fiscal year of the business-day-adjusted
593	     * registrationDate ends; the fiscal year starts on 1 July). {@code HASH8} is the first eight
594	     * upper-cased hex characters of the SHA-256 of {@code normalizedTelephone + lastName} (the same
595	     * hash used by the region-and-hash identity). {@code CHK} is a single Luhn check digit computed
596	     * over the digits of {@code '<REGION><FY><HASH8>'}, e.g. {@code 'NSW261A2B3C4D5'}.
597	     *
598	     * @param postcode the postcode of the owner being created, may be {@code null}
599	     * @param registrationDate the business-day-adjusted registration date of the owner being created
600	     * @param normalizedTelephone the E.164 telephone of the owner being created
601	     * @param lastName the last name of the owner being created
602	     * @return the formatted member id
603	     */
604	    private String memberId(String postcode, LocalDate registrationDate, String normalizedTelephone, String lastName) {
605	        String region = regionFromPostcode(postcode);
606	        String fiscalYear = String.format("%02d", fiscalYearEnding(registrationDate) % 100);
607	        String hash8 = sha256HexPrefix(normalizedTelephone + lastName, 8);
608	        String base = region + fiscalYear + hash8;
609	        return base + luhnCheckDigit(base);
610	    }
611	
612	    /**
613	     * The fiscal year in which a date falls, labelled by the calendar year in which the fiscal year
614	     * ends. The fiscal year starts on 1 July, so a date on or after 1 July belongs to the fiscal year
615	     * ending the following calendar year, and a date before 1 July belongs to the fiscal year ending
616	     * that calendar year.
617	     */
618	    private static int fiscalYearEnding(LocalDate date) {
619	        return date.getMonthValue() >= java.time.Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
620	    }
621	
622	    /**
623	     * The Luhn check digit (0-9) computed over the digits contained in {@code value}; non-digit
624	     * characters are ignored.
625	     */
626	    private static int luhnCheckDigit(String value) {
627	        int sum = 0;
628	        boolean dbl = true;
629	        for (int i = value.length() - 1; i >= 0; i--) {
630	            char c = value.charAt(i);
631	            if (c < '0' || c > '9') {
632	                continue;
633	            }
634	            int d = c - '0';
635	            if (dbl) {
636	                d *= 2;
637	                if (d > 9) {
638	                    d -= 9;
639	                }
640	            }
641	            sum += d;
642	            dbl = !dbl;
643	        }
644	        return (10 - (sum % 10)) % 10;
645	    }
646	
647	    /**
648	     * The owner's current primary identifier, as carried by the structured {@link OwnerCreatedEvent}:
649	     * its unified {@code memberId}.
650	     *
651	     * @param owner the owner just created
652	     * @return the owner's primary identifier
653	     */
654	    private String primaryIdentifier(Owner owner) {
655	        return owner.getMemberId();
656	    }
657	
658	    /**
659	     * De-duplicates a freshly computed member id against the member ids already held by existing
660	     * owners. When the id is unused it is returned unchanged; otherwise {@code '-<n>'} is appended
661	     * with the smallest {@code n} of 2 or more that yields an id no existing owner carries.
662	     *
663	     * @param memberId the computed member id for the owner being created
664	     * @return the same id when unique, otherwise the id with a {@code '-<n>'} suffix that makes it
665	     *     unique
666	     */
667	    private String deduplicateMemberId(String memberId) {
668	        Set<String> existing = new java.util.HashSet<>();
669	        for (Owner owner : this.clinicService.findAllOwners()) {
670	            if (owner.getMemberId() != null) {
671	                existing.add(owner.getMemberId());
672	            }
673	        }
674	        if (!existing.contains(memberId)) {
675	            return memberId;
676	        }
677	        int n = 2;
678	        while (existing.contains(memberId + "-" + n)) {
679	            n++;
680	        }
681	        return memberId + "-" + n;
682	    }
683	
684	    /**
685	     * Returns the region code whose inclusive postcode range contains the given 4-digit postcode
686	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), or {@code 'UNKNOWN'} when the postcode is
687	     * {@code null}, non-numeric, or in no known range.
688	     *
689	     * @param postcode the postcode, may be {@code null}
690	     * @return the region code, or {@code 'UNKNOWN'}
691	     */
692	    private static String regionFromPostcode(String postcode) {
693	        if (postcode == null || postcode.isBlank()) {
694	            return "UNKNOWN";
695	        }
696	        int code;
697	        try {
698	            code = Integer.parseInt(postcode.trim());
699	        } catch (NumberFormatException e) {
700	            return "UNKNOWN";
701	        }
702	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
703	            int[] range = entry.getValue();
704	            if (code >= range[0] && code <= range[1]) {
705	                return entry.getKey();
706	            }
707	        }
708	        return "UNKNOWN";
709	    }
710	
711	    /**
712	     * Computes the SHA-256 of {@code value} and returns its first {@code length} hex characters,
713	     * upper-cased.
714	     *
715	     * @param value the string to hash
716	     * @param length the number of leading hex characters to return
717	     * @return the upper-cased hex prefix of the digest
718	     */
719	    private static String sha256HexPrefix(String value, int length) {
720	        try {
721	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
722	            StringBuilder sb = new StringBuilder(digest.length * 2);
723	            for (byte b : digest) {
724	                sb.append(String.format("%02x", b));
725	            }
726	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
727	        } catch (NoSuchAlgorithmException e) {
728	            throw new IllegalStateException("SHA-256 not available", e);
729	        }
730	    }
731	
732	    /**
733	     * Counts the existing owners that share the owner-to-be's first and last name, compared
734	     * case-insensitively (surrounding whitespace trimmed). The count reflects the state before the
735	     * new owner is persisted, so it excludes the owner being created.
736	     *
737	     * @param firstName the first name of the owner being created
738	     * @param lastName the last name of the owner being created
739	     * @return the number of existing owners with the same first and last name
740	     */
741	    private int countNamesakes(String firstName, String lastName) {
742	        String normalizedFirstName = normalizeName(firstName);
743	        String normalizedLastName = normalizeName(lastName);
744	        return (int) this.clinicService.findAllOwners().stream()
745	            .filter(existing ->
746	                normalizedFirstName.equals(normalizeName(existing.getFirstName()))
747	                    && normalizedLastName.equals(normalizeName(existing.getLastName())))
748	            .count();
749	    }
750	
751	    /**
752	     * Counts the members of the owner-to-be's household after this create, i.e. one more than the
753	     * number of existing owners already carrying the same {@code householdId}. The household
754	     * identifier is a deterministic function of last name and postcode, so a solo owner (the only one
755	     * with that identifier) is a household of one. The count includes the owner being created (hence
756	     * the {@code + 1}).
757	     *
758	     * @param householdId the stable household identifier of the owner being created
759	     * @return the number of household members after this create (always at least 1)
760	     */
761	    private int householdSize(String householdId) {
762	        if (householdId == null) {
763	            return 1;
764	        }
765	        return (int) this.clinicService.findAllOwners().stream()
766	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
767	            .count() + 1;
768	    }
769	
770	    /**
771	     * Computes the household-capped membership level for the owner being created. The level starts as
772	     * the owner's own derived level (from its membership points). When at least one existing (active)
773	     * household member shares the owner's {@code householdId}, the level is capped so it may not exceed
774	     * one above the current maximum membership level among those existing members; with no existing
775	     * household member no cap applies and the derived level is returned unchanged. Returns {@code null}
776	     * when no level can be derived for the owner.
777	     *
778	     * @param owner the owner being created, with its level-affecting fields already populated
779	     * @param householdId the stable household identifier of the owner being created
780	     * @return the capped membership level, or {@code null} when none can be derived
781	     */
782	    private Integer cappedMembershipLevel(Owner owner, String householdId) {
783	        Integer level = ownerMapper.membershipLevel(owner);
784	        if (level == null || householdId == null) {
785	            return level;
786	        }
787	        java.util.OptionalInt maxExisting = activeOwners()
788	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
789	            .map(ownerMapper::membershipLevel)
790	            .filter(java.util.Objects::nonNull)
791	            .mapToInt(Integer::intValue)
792	            .max();
793	        if (maxExisting.isPresent()) {
794	            level = Math.min(level, maxExisting.getAsInt() + 1);
795	        }
796	        return level;
797	    }
798	
799	    /**
800	     * Normalizes a name for case-insensitive comparison by trimming surrounding whitespace and
801	     * lower-casing.
802	     *
803	     * @param value the raw name, may be {@code null}
804	     * @return the normalized name ({@code ""} when {@code value} is {@code null})
805	     */
806	    private static String normalizeName(String value) {
807	        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
808	    }
809	
810	    /**
811	     * The fixed city-to-region table used to validate a postcode against its city
812	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD). A city not in this table has no known region and
813	     * therefore accepts any 4-digit postcode.
814	     */
815	    private static final java.util.Map<String, String> CITY_REGION = java.util.Map.of(
816	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
817	
818	    /**
819	     * The fixed region-to-postcode-range table: each region admits an inclusive 4-digit range
820	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
821	     */
822	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
823	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
824	
825	    /**
826	     * Validates an owner's optional postcode on create. A {@code null} or blank postcode is left
827	     * untouched (postcode is optional when absent). When present it must be exactly four digits and,
828	     * when the city maps to a known region, must fall within that region's inclusive range
829	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit
830	     * postcode.
831	     *
832	     * @param city the city of the owner being created
833	     * @param postcode the raw postcode as supplied by the caller, may be {@code null}
834	     * @throws InvalidPostcodeException if a present postcode is not four digits or is out of range
835	     *     for the city's region
836	     */
837	    private static void validatePostcode(String city, String postcode) {
838	        if (postcode == null || postcode.isBlank()) {
839	            return;
840	        }
841	        if (!postcode.matches("\\d{4}")) {
842	            throw new InvalidPostcodeException("Postcode must be exactly 4 digits");
843	        }
844	        String region = CITY_REGION.get(city);
845	        int[] range = region == null ? null : REGION_POSTCODES.get(region);
846	        if (range != null) {
847	            int value = Integer.parseInt(postcode);
848	            if (value < range[0] || value > range[1]) {
849	                throw new InvalidPostcodeException(
850	                    "Postcode is out of range for the city's region");
851	            }
852	        }
853	    }
