865	    /**
866	     * Reads the caller-supplied {@code Idempotency-Key} header from the current request, if any. The
867	     * header is absent for ordinary creates; when present and non-blank it enables the idempotent-create
868	     * behaviour keyed on its value.
869	     *
870	     * @return the trimmed idempotency key, or {@code null} when the header is absent or blank
871	     */
872	    private static String currentIdempotencyKey() {
873	        var attributes = org.springframework.web.context.request.RequestContextHolder.getRequestAttributes();
874	        if (!(attributes instanceof org.springframework.web.context.request.ServletRequestAttributes servletAttributes)) {
875	            return null;
876	        }
877	        String key = servletAttributes.getRequest().getHeader("Idempotency-Key");
878	        return (key == null || key.isBlank()) ? null : key.trim();
879	    }
