881	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
882	    @Override
883	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
884	        String idempotencyKey = currentIdempotencyKey();
885	        if (idempotencyKey != null) {
886	            Integer existingId = idempotencyKeys.get(idempotencyKey);
887	            if (existingId != null) {
888	                Owner existing = this.clinicService.findOwnerById(existingId);
889	                if (existing != null) {
890	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
891	                }
892	            }
893	        }
894	        applyAddress(ownerFieldsDto);
895	        validateRequiredFields(ownerFieldsDto);
896	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
897	        if (registrationDate == null) {
898	            registrationDate = LocalDate.now();
899	        } else if (registrationDate.isAfter(LocalDate.now())) {
900	            throw new FutureRegistrationDateException(
901	                "registrationDate must not be later than the server date");
902	        }
903	        registrationDate = toBusinessDay(registrationDate);
904	        ownerFieldsDto.setRegistrationDate(registrationDate);
905	        rejectDailyOwnerLimit(registrationDate);
906	        rejectCityAtCapacity(ownerFieldsDto.getCity());
907	        validatePostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
908	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
909	        ownerFieldsDto.setTelephone(normalizedTelephone);
910	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
911	        ownerFieldsDto.setEmail(normalizedEmail);
912	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
913	        String ownerHouseholdId = householdId(ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
914	        String identityKey = deriveIdentityKey(normalizedTelephone, normalizedEmail, ownerFieldsDto.getLastName());
915	        rejectDuplicateIdentity(identityKey);
916	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicateOf(
917	            ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode(), identityKey);
918	        HttpHeaders headers = new HttpHeaders();
919	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
920	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
921	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
922	        owner.setMemberId(deduplicateMemberId(memberId(
923	            ownerFieldsDto.getPostcode(), registrationDate, normalizedTelephone, ownerFieldsDto.getLastName())));
924	        owner.setHouseholdId(ownerHouseholdId);
925	        owner.setHouseholdSize(householdSize(ownerHouseholdId));
926	        owner.setNamesakeCount(countNamesakes(ownerFieldsDto.getFirstName(), ownerFieldsDto.getLastName()));
927	        owner.setBulkSignupWarning(bulkSignupWarning(registrationDate));
928	        owner.setCapacityWarning(capacityWarning(ownerFieldsDto.getCity()));
929	        owner.setMembershipLevel(cappedMembershipLevel(owner, ownerHouseholdId));
930	        this.clinicService.saveOwner(owner);
931	        if (idempotencyKey != null) {
932	            idempotencyKeys.put(idempotencyKey, owner.getId());
933	        }
934	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
935	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
936	            ownerMapper.membershipLevel(owner));
937	        AUDIT.info(new OwnerCreatedEvent(AUDIT_SEQ.incrementAndGet(), owner.getId(),
938	            primaryIdentifier(owner), ownerMapper.membershipLevel(owner)).toJson());
939	        NOTIFY.info("welcome owner id={} memberId={}", owner.getId(), owner.getMemberId());
940	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
941	        headers.setLocation(UriComponentsBuilder.newInstance()
942	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
943	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
944	    }
