201	        }
202	        int points = 0;
203	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
204	        if (hasEmail) {
205	            points += 2;
206	        }
207	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
208	        if (noNamesakes) {
209	            points += 1;
210	        }
211	        boolean largeHousehold = owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3;
212	        if (largeHousehold) {
