256	     * is later than the fiscal year of its registrationDate (the fiscal year starts on 1 July).
257	     * Returns {@code false} when the registrationDate is absent (or in the future, which shares the
258	     * current fiscal year), so a newly created owner has no qualifying tenure.
259	     */
260	    default boolean hasQualifyingTenure(@Nullable Owner owner) {
261	        if (owner == null || owner.getRegistrationDate() == null) {
262	            return false;
263	        }
264	        int elapsedFiscalYears = fiscalYearEnding(java.time.LocalDate.now())
265	            - fiscalYearEnding(owner.getRegistrationDate());
