272	     * stored {@code '+61412345678'}. The country code is the single digit for the {@code +1} and
273	     * {@code +7} plans and two digits otherwise. Returns the raw value unchanged when it is not a
274	     * {@code '+'}-prefixed digit string, or {@code null} when absent.
275	     */
276	    default @Nullable String telephoneDisplay(@Nullable Owner owner) {
