281	        if (telephone == null || !telephone.matches("\\+\\d+")) {
282	            return telephone;
283	        }
284	        String digits = telephone.substring(1);
285	        int countryCodeLength = (digits.startsWith("1") || digits.startsWith("7")) ? 1 : 2;
286	        countryCodeLength = Math.min(countryCodeLength, digits.length());
287	        String countryCode = digits.substring(0, countryCodeLength);
288	        String national = digits.substring(countryCodeLength);
289	        StringBuilder sb = new StringBuilder("+").append(countryCode);
290	        for (int i = 0; i < national.length(); i += 3) {
291	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
292	        }
293	        return sb.toString();
294	    }
